typedef float vm_num_t;

class num_list
{
public:
  vm_num_t* start;
  vm_num_t* finish;
  vm_num_t* end_of_storage;

  unsigned int size() const { return finish - start; }
};

typedef num_list* vm_num_list_t;

class vm_stack
{
public:
  char* SP;

  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

void error(const char*);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    function(script_library_class*, const char*) {}
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()

#define SLF_RETURN \
  if (!stack.push((char*)&result, sizeof(result))) \
    error("script stack overflow")

#define SLF_DONE \
  return true

class slf_num_list_size_t : public script_library_class::function
{
public:
  slf_num_list_size_t(script_library_class* slc, const char* n)
    : script_library_class::function(slc, n) {}

  struct parms_t
  {
    vm_num_list_t me;
  };

  virtual bool operator()(vm_stack& stack, entry_t entry)
  {
    SLF_PARMS;
    vm_num_t result = parms->me->size();
    SLF_RETURN;
    SLF_DONE;
  }
};

slf_num_list_size_t slf_num_list_size(0, "size()");
